"""Capture quality gate for industrial visual inspection.

Evaluates raw optical captures before neural inference to reject blurred,
overexposed, underexposed, or low-contrast captures, preventing false alarms
and unreliable anomaly scoring.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple
import numpy as np


@dataclass(frozen=True)
class CaptureQualityReport:
    """Diagnostic report generated by the optical capture quality gate."""

    is_valid_capture: bool
    metrics: Dict[str, float]
    rejection_reasons: List[str] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)

    def summary(self) -> str:
        status = "VALID" if self.is_valid_capture else "REJECTED"
        reasons = "; ".join(self.rejection_reasons) if self.rejection_reasons else "None"
        return f"CaptureQuality [{status}] - Violations: {reasons}"


class CaptureQualityGate:
    """Validates raw optical camera captures prior to neural feature extraction.

    Parameters:
        min_laplacian_variance: Minimum variance of Laplacian to accept sharpness (blur test).
        min_mean_intensity: Minimum average pixel intensity (underexposure guard).
        max_mean_intensity: Maximum average pixel intensity (overexposure guard).
        min_contrast_rms: Minimum root-mean-square contrast.
        max_overexposed_pixel_pct: Maximum allowed percentage of saturated pixels (> 250).
        max_underexposed_pixel_pct: Maximum allowed percentage of near-zero pixels (< 5).
    """

    def __init__(
        self,
        min_laplacian_variance: float = 50.0,
        min_mean_intensity: float = 30.0,
        max_mean_intensity: float = 235.0,
        min_contrast_rms: float = 15.0,
        max_overexposed_pixel_pct: float = 0.05,
        max_underexposed_pixel_pct: float = 0.05,
    ) -> None:
        self.min_laplacian_variance = float(min_laplacian_variance)
        self.min_mean_intensity = float(min_mean_intensity)
        self.max_mean_intensity = float(max_mean_intensity)
        self.min_contrast_rms = float(min_contrast_rms)
        self.max_overexposed_pixel_pct = float(max_overexposed_pixel_pct)
        self.max_underexposed_pixel_pct = float(max_underexposed_pixel_pct)

    def _to_grayscale(self, image: np.ndarray) -> np.ndarray:
        """Converts an RGB or BGR image to grayscale using luminance weighting."""
        if image.ndim == 2:
            return image.astype(np.float32)
        if image.shape[2] == 1:
            return image[:, :, 0].astype(np.float32)
        # Rec. 601 luma coefficients
        gray = 0.299 * image[:, :, 0] + 0.587 * image[:, :, 1] + 0.114 * image[:, :, 2]
        return gray.astype(np.float32)

    def _compute_laplacian_variance(self, gray: np.ndarray) -> float:
        """Computes blur via discrete 2D Laplacian operator convolution."""
        # 3x3 Discrete Laplacian kernel: [[0, 1, 0], [1, -4, 1], [0, 1, 0]]
        h, w = gray.shape
        if h < 3 or w < 3:
            return 0.0
        # Fast vectorized discrete Laplacian using central difference slicing
        center = gray[1:-1, 1:-1]
        up = gray[0:-2, 1:-1]
        down = gray[2:, 1:-1]
        left = gray[1:-1, 0:-2]
        right = gray[1:-1, 2:]
        laplacian = up + down + left + right - 4.0 * center
        return float(np.var(laplacian))

    def evaluate(self, image: np.ndarray) -> CaptureQualityReport:
        """Assesses input capture image.

        Args:
            image: uint8 or float32 image array, shape (H, W, 3) or (H, W).

        Returns:
            CaptureQualityReport containing validity decision and diagnostic metrics.
        """
        if image is None or image.size == 0:
            return CaptureQualityReport(
                is_valid_capture=False,
                metrics={},
                rejection_reasons=["Empty or corrupted image frame received"],
            )

        # Normalize to 0-255 range if normalized float [0, 1] was provided
        arr = image.astype(np.float32)
        if arr.max() <= 1.0 and arr.min() >= 0.0:
            arr = arr * 255.0

        gray = self._to_grayscale(arr)
        total_pixels = float(gray.size)

        # 1. Blur Assessment
        laplacian_var = self._compute_laplacian_variance(gray)

        # 2. Exposure & Intensity Metrics
        mean_intensity = float(np.mean(gray))
        contrast_rms = float(np.std(gray))

        # 3. Saturation & Clipping Fractions
        overexposed_count = np.sum(gray >= 250.0)
        underexposed_count = np.sum(gray <= 5.0)
        overexposed_pct = float(overexposed_count / total_pixels)
        underexposed_pct = float(underexposed_count / total_pixels)

        metrics: Dict[str, float] = {
            "laplacian_variance": round(laplacian_var, 2),
            "mean_intensity": round(mean_intensity, 2),
            "contrast_rms": round(contrast_rms, 2),
            "overexposed_pixel_pct": round(overexposed_pct, 4),
            "underexposed_pixel_pct": round(underexposed_pct, 4),
        }

        reasons: List[str] = []
        warnings: List[str] = []

        if laplacian_var < self.min_laplacian_variance:
            reasons.append(
                f"Image is blurred: Laplacian variance ({laplacian_var:.1f}) < "
                f"threshold ({self.min_laplacian_variance:.1f})"
            )

        if mean_intensity < self.min_mean_intensity:
            reasons.append(
                f"Underexposed: mean intensity ({mean_intensity:.1f}) < "
                f"threshold ({self.min_mean_intensity:.1f})"
            )
        elif mean_intensity > self.max_mean_intensity:
            reasons.append(
                f"Overexposed: mean intensity ({mean_intensity:.1f}) > "
                f"threshold ({self.max_mean_intensity:.1f})"
            )

        if contrast_rms < self.min_contrast_rms:
            reasons.append(
                f"Low contrast: RMS contrast ({contrast_rms:.1f}) < "
                f"threshold ({self.min_contrast_rms:.1f})"
            )

        if overexposed_pct > self.max_overexposed_pixel_pct:
            reasons.append(
                f"Severe specular highlights: {overexposed_pct*100:.1f}% pixels saturated "
                f"(max {self.max_overexposed_pixel_pct*100:.1f}%)"
            )

        if underexposed_pct > self.max_underexposed_pixel_pct:
            warnings.append(
                f"High black level: {underexposed_pct*100:.1f}% pixels crushed to zero"
            )

        is_valid = len(reasons) == 0
        return CaptureQualityReport(
            is_valid_capture=is_valid,
            metrics=metrics,
            rejection_reasons=reasons,
            warnings=warnings,
        )
